/** 
 * Processes the content-modify  {@link JingleIQ}.
 * @param content The {@link JingleIQ} that contains content that remotepeer wants to be modified
 */
public void processContentModify(JingleIQ content){
  try {
    ContentPacketExtension ext = content.getContentList().get(0);
    SendersEnum senders = ext.getSenders();
    try {
      getMediaHandler().reinitContent(ext.getName(), senders);
    } catch (Exception exc) {
      logger.info("Failed to process an incoming content-modify", exc);
      JingleIQ errResp = JinglePacketFactory.createSessionTerminate(sessionInitIQ.getTo(), sessionInitIQ.getFrom(), sessionInitIQ.getSID(), Reason.INCOMPATIBLE_PARAMETERS, "Error: " + exc.getMessage());
      setState(CallPeerState.FAILED, "Error: " + exc.getMessage());
      getProtocolProvider().getConnection().sendPacket(errResp);
      return;
    }
  } catch (IndexOutOfBoundsException | ClassCastException | NullPointerException e) {
    logger.error("Runtime error occurred while processing content-modify: " + e.getMessage(), e);
    JingleIQ errResp = JinglePacketFactory.createSessionTerminate(sessionInitIQ.getTo(), sessionInitIQ.getFrom(), sessionInitIQ.getSID(), Reason.INCOMPATIBLE_PARAMETERS, "Runtime Error: " + e.getMessage());
    setState(CallPeerState.FAILED, "Runtime Error: " + e.getMessage());
    getProtocolProvider().getConnection().sendPacket(errResp);
  }
}
